mapper.select:
SELECT warehouse_name,receive_unit, count(outbound_num) as count FROM `idevelop_device_outbound` WHERE
outbound_time BETWEEN #{startDate} AND #{endDate} and
is_deleted = 0 and warehouse = #{warehouse}

select ido.*
from idevelop_device_outbound ido left join idevelop_device_outbound_detail idod on ido.id = idod.outbound_id

    ido.is_deleted = 0
    
        AND idod.device_code LIKE CONCAT('%', #{deviceOutboundDTO.deviceCode}, '%')
    
    
        AND ido.outbound_no LIKE CONCAT('%', #{deviceOutboundDTO.outboundNo}, '%')
    
    
        AND ido.operation_no LIKE CONCAT('%', #{deviceOutboundDTO.operationNo}, '%')
    
    
        AND ido.apply_no LIKE CONCAT('%', #{deviceOutboundDTO.applyNo}, '%')
    
    
        AND ido.device_category = #{deviceOutboundDTO.deviceCategory}
    
    
        AND ido.device_type = #{deviceOutboundDTO.deviceType}
    
    
        AND ido.region_code LIKE CONCAT(#{deviceOutboundDTO.regionCode}, '%')
    
    
        AND ido.receive_unit = #{deviceOutboundDTO.receiveUnit}
    
    
        AND ido.receive_duty_dept = #{deviceOutboundDTO.receiveDutyDept}
    
    
        AND outbound_time BETWEEN #{deviceOutboundDTO.beginTime} AND #{deviceOutboundDTO.endTime}
    
    GROUP BY ido.id ORDER BY ido.create_time DESC
